<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>注册</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            padding: 0;
        }
        .header {
            background-color: #007bff;
            color: #fff;
            padding: 1rem;
            text-align: center;
        }
        .header h1 {
            margin: 0;
        }
        .nav {
            background-color: #f0f0f0;
            padding: 0.5rem;
            text-align: center;
        }
        .nav a {
            color: #337ab7;
            text-decoration: none;
            margin: 0 1rem;
        }
        .nav a:hover {
            color: #23527c;
        }
        .form {
            padding: 2rem;
        }
        .form input, .form select {
            width: 100%;
            padding: 0.5rem;
            margin-bottom: 1rem;
            border: 1px solid #ccc;
        }
        .form button {
            background-color: #007bff;
            color: #fff;
            padding: 0.5rem 1rem;
            border: none;
            border-radius: 0.25rem;
            cursor: pointer;
        }
        .form button:hover {
            background-color: #0069d9;
        }
        .footer {
            background-color: #007bff;
            color: #fff;
            padding: 1rem;
            text-align: center;
            clear: both;
        }
    </style>
</head>
<body>
    <div class="header">
        <h1>注册</h1>
    </div>
    <div class="nav">
        <a href="index.html">首页</a>
        <a href="courses.html">课程</a>
        <a href="about.html">关于</a>
    </div>
    <div class="form">
        <form>
            <input type="text" placeholder="姓名">
            <input type="email" placeholder="邮箱">
            <select>
                <option value="">请选择课程</option>
                <option value="">英语课程</option>
                <option value="">编程课程</option>
            </select>
            <button>注册</button>
        </form>
    </div>
    <div class="footer">
        <p>&copy; 2023 学途</p>
    </div>
</body>
</html>
